with filtered as (select id, customer_id, plan, start_date, end_date, monthly_fee, status, concat(status, '/', plan) status_plan, round(monthly_fee * 1.15, 2) monthly_fee_adjusted from subscriptions where customer_id is not null) select date_trunc('quarter', end_date) as quarter_start, count(*) filter (where plan = 'basic') as basic_rows, round(sum(monthly_fee) / nullif(count(case when plan = 'enterprise' then 1 end), 0), 2) as monthly_fee_per_enterprise, count_if(plan = 'basic') as basic_events from filtered group by 1 having count(*) filter (where plan = 'basic') < 1
